{{FrontSide}}

<div class="section sentence">
<blockquote>
{{Sentence}}
<cite>{{Source}}</cite>
</blockquote>
</div>
<div class="section translation">{{Translation}}</div>
<div class="section note">{{Note}}</div>
<div class="section backlink">{{Backlink}}</div>

<script>
(function() {
    const script = document.createElement('script');
    script.src = "https://cdnjs.cloudflare.com/ajax/libs/marked/16.0.0/lib/marked.umd.min.js";
    script.onload = () => {
        try {
            const note = document.getElementsByClassName('section note')[0].innerHTML;
            const noteHtml = marked.parse(note);
            document.getElementsByClassName('section note')[0].innerHTML = noteHtml;
        } catch (error) {
            console.error("Error parsing note:", error);
        }
    };
    document.body.appendChild(script);
})()
</script>

